{"command": "python3 <<'PY'
def lcs_table(a,b):
    n,m=len(a),len(b)
    t=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for j in range(1,m+1):
            if a[i-1]==b[j-1]:
                t[i][j]=t[i-1][j-1]+1
            else:
                t[i][j]=max(t[i-1][j], t[i][j-1])
    return t

def backtrack(a,b,t, prefer='left'):
    # prefer 'left' means when t[i-1][j]==t[i][j-1], choose left (i-1) vs up?
    # Standard: at (i,j), if a[i-1]==b[j-1], take diagonal; else if t[i-1][j] > t[i][j-1], go up (delete), elif <, go left (insert), else tie -> prefer
    i,j=len(a),len(b)
    ops=[] # list of (type, char)
    while i>0 and j>0:
        if a[i-1]==b[j-1]:
            ops.append(('both', a[i-1]))
            i-=1; j-=1
        elif t[i-1][j] > t[i][j-1]:
            ops.append(('left', a[i-1])) # delete
            i-=1
        elif t[i-1][j] < t[i][j-1]:
            ops.append(('right', b[j-1])) # insert
            j-=1
        else: # tie
            if prefer=='left':
                ops.append(('left', a[i-1]))
                i-=1
            else:
                ops.append(('right', b[j-1]))
                j-=1
    while i>0:
        ops.append(('left', a[i-1])); i-=1
    while j>0:
        ops.append(('right', b[j-1])); j-=1
    ops.reverse()
    return ops

def ops_to_display(ops):
    # display new string with colors: green for both, red for right, ignore left
    # group consecutive same colors
    res=[]
    cur=None
    curstr=""
    for typ,ch in ops:
        if typ=='left':
            # flush?
            if cur is not None:
                res.append((cur,curstr)); cur=None; curstr=""
            # left ignored, but breaks grouping? Let's see: if we flush on left, then boths separated by left will be separate chunks
            # if we don't flush, they'd merge
            # For display, left is invisible, but does it break green grouping? Observed splits suggest YES (left breaks grouping)
            continue
        elif typ=='both':
            col='green'
        elif typ=='right':
            col='red'
        if cur==col:
            curstr+=ch
        else:
            if cur is not None:
                res.append((cur,curstr))
            cur=col; curstr=ch
    if cur is not None:
        res.append((cur,curstr))
    return res

def ops_to_display_merge(ops):
    # merge across left (ignore left without breaking)
    res=[]
    cur=None; curstr=""
    for typ,ch in ops:
        if typ=='left':
            continue
        col='green' if typ=='both' else 'red'
        if cur==col:
            curstr+=ch
        else:
            if cur is not None:
                res.append((cur,curstr))
            cur=col; curstr=ch
    if cur is not None:
        res.append((cur,curstr))
    return res

for a,b in [("hello","heXlo"), ("aab","Xab"), ("aaab","Xaab"), ("abcde","aXcde"), ("abbbc","aXbbc")]:
    t=lcs_table(a,b)
    print(f"=== {a} -> {b} ===")
    for pref in ['left','right']:
        ops=backtrack(a,b,t,prefer=pref)
        print(f" prefer {pref}: {ops}")
        print(f"  display (break on left): {ops_to_display(ops)}")
        print(f"  display (merge): {ops_to_display_merge(ops)}")
PY
"}

