{"command": "python3 <<'PY'
def lcs_prefix(a,b):
    n,m=len(a),len(b)
    t=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for j in range(1,m+1):
            if a[i-1]==b[j-1]:
                t[i][j]=t[i-1][j-1]+1
            else:
                t[i][j]=max(t[i-1][j], t[i][j-1])
    return t

def lcs_suffix(a,b):
    n,m=len(a),len(b)
    t=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if a[i]==b[j]:
                t[i][j]=t[i+1][j+1]+1
            else:
                t[i][j]=max(t[i+1][j], t[i][j+1])
    # t[i][j] for i in 0..n, j in 0..m, where t[n][*]=t[*][m]=0
    # Need to handle boundaries: our t is (n+1)x(m+1) with t[n][j]=0, t[i][m]=0
    return t

def backtrack_end(a,b,t, tie='left'):
    i,j=len(a),len(b)
    ops=[]
    while i>0 and j>0:
        if a[i-1]==b[j-1]:
            ops.append(('both',a[i-1])); i-=1; j-=1
        elif t[i-1][j] > t[i][j-1]:
            ops.append(('left',a[i-1])); i-=1
        elif t[i-1][j] < t[i][j-1]:
            ops.append(('right',b[j-1])); j-=1
        else:
            if tie=='left':
                ops.append(('left',a[i-1])); i-=1
            else:
                ops.append(('right',b[j-1])); j-=1
    while i>0:
        ops.append(('left',a[i-1])); i-=1
    while j>0:
        ops.append(('right',b[j-1])); j-=1
    ops.reverse()
    return ops

def backtrack_start(a,b,t, tie='left'):
    # t is suffix table: t[i][j] = LCS of a[i:] and b[j:]
    n,m=len(a),len(b)
    i,j=0,0
    ops=[]
    while i<n and j<m:
        if a[i]==b[j] and t[i][j]==t[i+1][j+1]+1:
            # Check if taking diagonal is optimal? Need to ensure t[i][j]==t[i+1][j+1]+1
            # If yes, take it (greedy). But there might be alternative with same length that doesn't take diagonal?
            # To get earliest, we take diagonal whenever possible? To get latest, we might skip?
            # Let's implement logic: if a[i]==b[j], we have option to take it if it leads to optimal.
            # For earliest, take it immediately. For latest, skip if alternative also optimal?
            # We'll implement earliest: take diagonal if optimal.
            # For latest: only take diagonal if forced? Hmm.
            ops.append(('both',a[i])); i+=1; j+=1
        elif t[i+1][j] >= t[i][j+1]:
            # delete vs insert? Need to check tie
            if t[i+1][j] > t[i][j+1]:
                ops.append(('left',a[i])); i+=1
            elif t[i+1][j] < t[i][j+1]:
                ops.append(('right',b[j])); j+=1
            else:
                if tie=='left':
                    ops.append(('left',a[i])); i+=1
                else:
                    ops.append(('right',b[j])); j+=1
        else:
            ops.append(('right',b[j])); j+=1
    while i<n:
        ops.append(('left',a[i])); i+=1
    while j<m:
        ops.append(('right',b[j])); j+=1
    return ops

def display(ops, break_on_left=True):
    res=[]; cur=None; curstr=""
    for typ,ch in ops:
        if typ=='left':
            if break_on_left and cur is not None:
                res.append((cur,curstr)); cur=None; curstr=""
            continue
        col='green' if typ=='both' else 'red'
        if cur==col:
            curstr+=ch
        else:
            if cur is not None:
                res.append((cur,curstr))
            cur=col; curstr=ch
    if cur is not None:
        res.append((cur,curstr))
    return res

tests = [
    ("hello","heXlo", [('green','he'),('red','X'),('green','l'),('green','o')]),
    ("aab","Xab", [('red','X'),('green','a'),('green','b')]),
    ("aaab","Xaab", [('red','X'),('green','aa'),('green','b')]),
    ("abcde","aXcde", [('green','a'),('red','X'),('green','cde')]),
    ("abbbc","aXbbc", [('green','a'),('red','X'),('green','bb'),('green','c')]), # observed split bb|c ?
    # Actually for abbbc b->X, old abbbc vs new aXbbc: observed was "a" green, "X" red, "bb" green, "c" green (split)
    ("hello","helolo", [('green','hel'),('red','o'),('green','lo')]),
]

for a,b,expected in tests:
    print(f"=== {a}->{b} expected {expected}")
    t_pre=lcs_prefix(a,b)
    for tie in ['left','right']:
        ops=backtrack_end(a,b,t_pre,tie=tie)
        print(f"  end tie {tie}: {display(ops)} ops={ops}")
    t_suf=lcs_suffix(a,b)
    for tie in ['left','right']:
        ops=backtrack_start(a,b,t_suf,tie=tie)
        print(f"  start tie {tie}: {display(ops)} ops={ops}")
PY
