                .arg(Arg::new("recursive").short('r').long("recursive").action(ArgAction::SetTrue).help("Recursive mode"))
                .arg(Arg::new("max-depth").short('d').long("max-depth").value_name("LEVEL").value_parser(value_parser!(usize)).requires("recursive").help("Set max depth in recursive mode"))
                .arg(Arg::new("hidden").short('x').long("hidden").action(ArgAction::SetTrue).requires("recursive").help("Include hidden files and directories"))
        )
        .subcommand(
            common(Command::new("from-file").about("Read operations from a dump file"))
                .arg(Arg::new("dumpfile").value_name("DUMPFILE").required(true))
                .arg(Arg::new("undo").short('u').long("undo").action(ArgAction::SetTrue).help("Undo the operations from the dump file"))
        )
        .subcommand(
            common(Command::new("to-ascii").about("Replace file name UTF-8 chars with ASCII chars representation"))
                .arg(Arg::new("paths").value_name("PATH(S)").help("Target paths").required(true).num_args(1..))
                .arg(Arg::new("include-dirs").short('D').long("include-dirs").action(ArgAction::SetTrue).help("Rename matching directories"))
                .arg(Arg::new("recursive").short('r').long("recursive").action(ArgAction::SetTrue).help("Recursive mode"))
                .arg(Arg::new("max-depth").short('d').long("max-depth").value_name("LEVEL").value_parser(value_parser!(usize)).requires("recursive").help("Set max depth in recursive mode"))
                .arg(Arg::new("hidden").short('x').long("hidden").action(ArgAction::SetTrue).requires("recursive").help("Include hidden files and directories"))
        )
}

// Color helpers
const RED: &str = "\x1b[31m";
const GREEN: &str = "\x1b[32m";
const GREY: &str = "\x1b[38;5;8m";
const BOLD_RED: &str = "\x1b[1;31m";
const BOLD: &str = "\x1b[1m";
const RESET: &str = "\x1b[0m";

fn color_enabled(mode: &str, is_stdout: bool) -> bool {
    match mode {
        "always" => true,
        "never" => false,
        "auto" => {
            if is_stdout {
                std::io::stdout().is_terminal()
            } else {
                std::io::stderr().is_terminal()
            }
        }
        _ => false,
    }
}

// Forward LCS diff for coloring
fn diff_ops(old: &str, new: &str) -> Vec<(char, char)> {
    // Returns Vec of (kind, ch) where kind: 'b'=both, 'r'=right(insert), 'l'=left(delete)
    // Forward LCS with suffix table, prefer insert on tie, greedy diagonal
    let a: Vec<char> = old.chars().collect();
    let b: Vec<char> = new.chars().collect();
    let n = a.len();
    let m = b.len();
    // suffix table t[i][j] = LCS of a[i..] and b[j..]
    let mut t = vec![vec![0usize; m+1]; n+1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            if a[i]==b[j] {
                t[i][j]=t[i+1][j+1]+1;
            } else {
                t[i][j]=std::cmp::max(t[i+1][j], t[i][j+1]);
            }
        }
    }
    let mut ops = Vec::new();
    let mut i=0usize; let mut j=0usize;
    while i<n && j<m {
        if a[i]==b[j] && t[i][j]==t[i+1][j+1]+1 {
            ops.push(('b', a[i]));
            i+=1; j+=1;
        } else if t[i+1][j] > t[i][j+1] {
            ops.push(('l', a[i]));
            i+=1;
        } else if t[i+1][j] < t[i][j+1] {
            ops.push(('r', b[j]));
            j+=1;
        } else {
            // tie -> prefer right (insert)
            ops.push(('r', b[j]));
            j+=1;
        }
    }
    while i<n { ops.push(('l', a[i])); i+=1; }
    while j<m { ops.push(('r', b[j])); j+=1; }
    ops
}

fn print_operation(src: &str, dst: &str, use_color: bool) -> String {
    if !use_color {
        return format!("{} -> {}\n", src, dst);
    }
    // split src/dst into parent and filename
    let src_path = Path::new(src);
    let dst_path = Path::new(dst);
    let src_parent = src_path.parent().and_then(|p| {
        let s = p.to_string_lossy().to_string();
        if s.is_empty() { None } else { Some(s) }
    });
    let dst_parent = dst_path.parent().and_then(|p| {
        let s = p.to_string_lossy().to_string();
        if s.is_empty() { None } else { Some(s) }
    });
    let src_file = src_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| src.to_string());
    let dst_file = dst_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| dst.to_string());
    // Handle case where src has no parent but dst has parent? Use each's own parent
    // For display, parent strings with trailing slash if non-empty
    let mut out = String::new();
    // old parent + filename grey
    if let Some(p) = src_parent {
        // parent display: p + "/"
        out.push_str(&format!("{}{}/{}", GREY, p, RESET));
        out.push_str(&format!("{}{}{}", GREY, src_file, RESET));
    } else {
        // check if src contains '/'? Actually if src is like "a.txt" with no parent, just filename
        // But what about src like "./a.txt"? parent is "."? Path parent of "./a.txt" is "."? Let's handle: if src contains '/', but parent empty? Unlikely.
        // For safety, if src has no parent, just print filename grey
        // However, need to handle src like "sub/a.txt" where parent is "sub" -> already handled
        out.push_str(&format!("{}{}{}", GREY, src_file, RESET));
        // Special case: if src is like "a.txt" but Path parent is "" (empty), we already handled.
        // If src has parent "" but actually contains '/'? No.
    }
    out.push_str(" -> ");
    // new parent green
    if let Some(p) = dst_parent {
        out.push_str(&format!("{}{}/{}", GREEN, p, RESET));
    } else {
        // no parent, nothing
    }
    // new filename with diff coloring
    let ops = diff_ops(&src_file, &dst_file);
    // Group consecutive same-kind (b together, r together), l breaks but not printed
    let mut idx=0;
    while idx < ops.len() {
        let kind = ops[idx].0;
        if kind=='l' {
            idx+=1;
            continue;
        }
        // collect consecutive same kind (b or r), but l breaks (already skipped, so consecutive in ops after skipping l? Actually need to consider that l in between breaks grouping.
        // Our loop naturally breaks because l is skipped with flush? Let's implement grouping that flushes on l.
        // Since we skip l without grouping, consecutive b's separated by l will be separate groups (as desired).
        // But consecutive b's without l should be grouped.
        let mut s = String::new();
        let cur_kind = kind;
        while idx < ops.len() && ops[idx].0==cur_kind {
            s.push(ops[idx].1);
            idx+=1;
        }
        // Now, if next is l, we will handle in next iteration (which will skip and thus break grouping for following)
        // But need to ensure that after collecting, if next is l, we flush (which we do by pushing group now)
        if cur_kind=='b' {
            out.push_str(&format!("{}{}{}", GREEN, s, RESET));
        } else { // 'r'
            out.push_str(&format!("{}{}{}", BOLD_RED, s, RESET));
        }
        // If next is l, the next iteration will skip it, but we have already flushed current group, so next b will be new group (split). Good.
    }
    out.push('\n');
    out
}

// ASCII transliteration - placeholder, will be replaced with generated table
fn transliterate_char(c: char) -> String {
    // For ascii, return as is
    if c.is_ascii() {
        return c.to_string();
    }
    // Use generated table if available, else fallback
    if let Some(s) = lookup_deunicode(c) {
        return s.to_string();
    }
    // Fallback: remove? (empty)
    String::new()
}

fn to_ascii_str(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        out.push_str(&transliterate_char(c));
    }
    out
}

