// Color helpers
const RED: &str = "\x1b[31m";
const GREEN: &str = "\x1b[32m";
const GREY: &str = "\x1b[38;5;8m";
const BOLD_RED: &str = "\x1b[1;31m";
const BOLD: &str = "\x1b[1m";
const RESET: &str = "\x1b[0m";

fn color_enabled(mode: &str, is_stdout: bool) -> bool {
    match mode {
        "always" => true,
        "never" => false,
        "auto" => {
            if is_stdout {
                std::io::stdout().is_terminal()
            } else {
                std::io::stderr().is_terminal()
            }
        }
        _ => false,
    }
}

// Forward LCS diff for coloring
fn diff_ops(old: &str, new: &str) -> Vec<(char, char)> {
    // Returns Vec of (kind, ch) where kind: 'b'=both, 'r'=right(insert), 'l'=left(delete)
    // Forward LCS with suffix table, prefer insert on tie, greedy diagonal
    let a: Vec<char> = old.chars().collect();
    let b: Vec<char> = new.chars().collect();
    let n = a.len();
    let m = b.len();
    // suffix table t[i][j] = LCS of a[i..] and b[j..]
    let mut t = vec![vec![0usize; m+1]; n+1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            if a[i]==b[j] {
                t[i][j]=t[i+1][j+1]+1;
            } else {
                t[i][j]=std::cmp::max(t[i+1][j], t[i][j+1]);
            }
        }
    }
    let mut ops = Vec::new();
    let mut i=0usize; let mut j=0usize;
    while i<n && j<m {
        if a[i]==b[j] && t[i][j]==t[i+1][j+1]+1 {
            ops.push(('b', a[i]));
            i+=1; j+=1;
        } else if t[i+1][j] > t[i][j+1] {
            ops.push(('l', a[i]));
            i+=1;
        } else if t[i+1][j] < t[i][j+1] {
            ops.push(('r', b[j]));
            j+=1;
        } else {
            // tie -> prefer right (insert)
            ops.push(('r', b[j]));
            j+=1;
        }
    }
    while i<n { ops.push(('l', a[i])); i+=1; }
    while j<m { ops.push(('r', b[j])); j+=1; }
    ops
}

fn print_operation(src: &str, dst: &str, use_color: bool) -> String {
    if !use_color {
        return format!("{} -> {}\n", src, dst);
    }
