    target: String,
}

fn main() {
    let cmd = build_cli();
    let matches = cmd.get_matches();
    let (sub, sub_matches) = matches.subcommand().unwrap();
    // common flags
    let is_force = sub_matches.get_flag("force");
    let is_silent = sub_matches.get_flag("silent");
    let color_mode = sub_matches.get_str("color").unwrap_or("auto");
    let use_color_out = color_enabled(color_mode, true);
    let use_color_err = color_enabled(color_mode, false);
    let do_backup = sub_matches.get_flag("backup");
    let dump_flag = sub_matches.get_flag("dump");
    let no_dump_flag = sub_matches.get_flag("no-dump");
    let dump_prefix = sub_matches.get_str("dump-prefix").unwrap_or("rnr-").to_string();
    let should_dump = if no_dump_flag { false } else if dump_flag { true } else if is_force { true } else { false };
    let is_dry = !is_force;

    match sub {
        "regex" => {
            let expr = sub_matches.get_str("expression").unwrap();
            let repl = sub_matches.get_str("replacement").unwrap();
            let paths: Vec<String> = sub_matches.get_many::<String>("paths").unwrap().cloned().collect();
            let limit_opt: Option<usize> = sub_matches.get_one::<usize>("replace-limit").copied();
            let limit = limit_opt.unwrap_or(1);
            let transform: Option<String> = sub_matches.get_one::<String>("replace-transform").cloned();
            let include_dirs = sub_matches.get_flag("include-dirs");
            let recursive = sub_matches.get_flag("recursive");
            let max_depth: Option<usize> = sub_matches.get_one::<usize>("max-depth").copied();
            let hidden = sub_matches.get_flag("hidden");

            // compile regex
            let re = match Regex::new(expr) {
                Ok(r) => r,
                Err(e) => {
                    // Error: Bad expression provided
                    let msg = format!("Error: Bad expression provided\n\n{}\n", e);
                    if use_color_err {
                        eprint!("{}Error: {}Bad expression provided\n\n{}{}{}\n", RED, RESET, RED, e, RESET);
                    } else {
                        eprint!("{}", msg);
                    }
                    std::process::exit(1);
                }
            };

            // collect candidates
            let candidates = collect_candidates(&paths, include_dirs, recursive, max_depth, hidden);
            // For regex, candidates are files/dirs that exist (via symlink_metadata). collect_candidates already filters existence? Need to ensure.
            // Compute operations
            let mut ops: Vec<(String,String)> = Vec::new();
            for cand in candidates {
                // cand is path string as given/discovered
                let p = Path::new(&cand);
                // get filename
                let fname = match p.file_name().and_then(|s| s.to_str()) {
                    Some(f) => f.to_string(),
                    None => continue,
                };
                // check if dir vs file filtering already done? For non-recursive explicit dirs without include-dirs, candidates should exclude dirs. For recursive, candidates include only desired types.
                // Apply regex replacement with limit and transform
                let new_fname_opt = apply_replacement(&re, &fname, repl, limit, transform.as_deref());
                if let Some(new_fname) = new_fname_opt {
                    if new_fname == fname {
                        continue;
                    }
                    // construct new path: parent + new_fname
                    let parent = p.parent();
                    let new_path = if let Some(par) = parent {
                        let par_str = par.to_string_lossy().to_string();
                        if par_str.is_empty() {
                            new_fname
                        } else {
                            format!("{}/{}", par_str, new_fname)
                        }
                    } else {
                        new_fname
                    };
                    // Edge: if original path ends with '/'? Unlikely. Ignore.
                    ops.push((cand, new_path));
                }
            }

            handle_operations(ops, is_dry, is_silent, use_color_out, use_color_err, do_backup, should_dump, dump_prefix);
        }
        "from-file" => {
            let dumpfile = sub_matches.get_str("dumpfile").unwrap();
            let undo = sub_matches.get_flag("undo");
            // read dump file
            let content = match fs::read_to_string(dumpfile) {
                Ok(c) => c,
                Err(_) => {
                    if !is_silent {
                        if is_dry {
                            print_header(use_color_out, is_silent);
                        }
                        if use_color_err {
                            eprint!("{}Error: {}Cannot open/read file {}{}{}\n", RED, RESET, RED, dumpfile, RESET);
                        } else {
                            eprint!("Error: Cannot open/read file {}\n", dumpfile);
                        }
                    }
                    std::process::exit(1);
                }
            };
            let dump: DumpFile = match serde_json::from_str(&content) {
                Ok(d) => d,
                Err(_) => {
                    if !is_silent {
                        if is_dry {
                            print_header(use_color_out, is_silent);
                        }
                        if use_color_err {
                            eprint!("{}Error: {}Cannot parse JSON file {}{}{}\n", RED, RESET, RED, dumpfile, RESET);
                        } else {
                            eprint!("Error: Cannot parse JSON file {}\n", dumpfile);
                        }
                    }
                    std::process::exit(1);
                }
            };
            let mut ops: Vec<(String,String)> = dump.operations.into_iter().map(|o| {
                if undo {
                    (o.target, o.source)
                } else {
                    (o.source, o.target)
                }
            }).collect();
            // from-file does not filter missing? It keeps all ops as in file (even if source missing). Good.
            // But should it filter no-change? If source==target, skip? Likely yes (no op). Let's filter.
            ops.retain(|(s,t)| s!=t);
            handle_operations(ops, is_dry, is_silent, use_color_out, use_color_err, do_backup, should_dump, dump_prefix);
        }
        "to-ascii" => {
            let paths: Vec<String> = sub_matches.get_many::<String>("paths").unwrap().cloned().collect();
            let include_dirs = sub_matches.get_flag("include-dirs");
            let recursive = sub_matches.get_flag("recursive");
            let max_depth: Option<usize> = sub_matches.get_one::<usize>("max-depth").copied();
            let hidden = sub_matches.get_flag("hidden");
            let candidates = collect_candidates(&paths, include_dirs, recursive, max_depth, hidden);
            let mut ops: Vec<(String,String)> = Vec::new();
            for cand in candidates {
                let p = Path::new(&cand);
                let fname = match p.file_name().and_then(|s| s.to_str()) {
                    Some(f) => f.to_string(),
                    None => continue,
                };
                let new_fname = to_ascii_str(&fname);
                if new_fname == fname {
                    continue;
                }
                // If transliteration results in empty? e.g., filename with only non-ascii that maps to ""? Then new_fname could be ""? What happens? Let's see: file "é.txt"? Actually "é" -> "e", not empty. For control char file? e.g., file "\x80.txt" -> ".txt"? That would be new filename ".txt" (hidden? Actually ".txt" starts with dot, hidden). That's allowed? Probably yes. If entire filename maps to ""? e.g., file "é" (no extension) -> "e"? Not empty. For file with single char that maps to "" (e.g., control), new filename ""? That would be empty string, parent + ""? That would be parent dir itself? Unlikely tested. We'll handle: if new_fname empty, skip? Or construct? Let's just construct as parent + new_fname (which could be empty -> parent). But then target would be parent dir, which exists => conflict? Hmm. For now, allow.
                let parent = p.parent();
                let new_path = if let Some(par) = parent {
                    let par_str = par.to_string_lossy().to_string();
                    if par_str.is_empty() {
                        new_fname
                    } else {
                        // Edge: if new_fname empty, new_path would be parent + "/"? Actually format!("{}/{}", par, "") gives "par/" with trailing slash. That's weird. But unlikely.
                        format!("{}/{}", par_str, new_fname)
                    }
                } else {
                    new_fname
                };
                ops.push((cand, new_path));
            }
            handle_operations(ops, is_dry, is_silent, use_color_out, use_color_err, do_backup, should_dump, dump_prefix);
        }
        _ => unreachable!(),
    }
}

fn print_header(use_color: bool, is_silent: bool) {
    if is_silent { return; }
    if use_color {
        println!("{}This is a DRY-RUN{}", BOLD, RESET);
    } else {
        println!("This is a DRY-RUN");
    }
}

fn collect_candidates(paths: &[String], include_dirs: bool, recursive: bool, max_depth: Option<usize>, hidden: bool) -> Vec<String> {
    let mut out = Vec::new();
    for input in paths {
        let p = Path::new(input);
        // Check existence via symlink_metadata (to include broken symlinks, exclude missing)
        if fs::symlink_metadata(p).is_err() {
            // For dirs that don't exist? Also check: if input is dir that doesn't exist, ignore.
            // For recursive, if input is missing, ignore (no ops, no error). As observed, missing gives just header, no error.
            continue;
        }
        let is_dir = p.is_dir();
        if is_dir {
            if recursive {
                // walk
                let mut builder = walkdir::WalkDir::new(p);
                if let Some(d) = max_depth {
                    builder = builder.max_depth(d);
                }
                // walkdir by default includes hidden, we filter manually
                // Also need to handle hidden pruning: if hidden==false, skip hidden files/dirs (and prune hidden dirs)
                // Use filter_entry?
                let walker = builder.contents_first(false).into_iter();
                for entry in walker {
                    let entry = match entry {
                        Ok(e) => e,
                        Err(_) => continue,
                    };
                    let entry_path = entry.path();
                    // Skip root itself? Walk includes root (depth 0). Should we include root if it matches and include-dirs? Yes, as observed: recursive on mydir_old with -D includes mydir_old itself (depth0). So include root.
                    // But need to handle hidden filtering for root? If root itself is hidden and hidden==false, should we include? For explicit hidden dir with recursive? Example: input is hidden dir itself (explicit), hidden==false, recursive: should we include its files? The root is explicit, so hidden check should not exclude root itself? But for its children, hidden check applies.
                    // Simplify: for depth 0 (root), don't filter hidden (since explicit). For others, filter.
                    let depth = entry.depth();
                    if depth==0 {
                        // root: check if dir vs file? Root is dir (since we are in dir branch). If include-dirs and root name matches? Actually root's filename matching will be handled later (for regex/to-ascii, we compute new name based on filename). For collection, we just collect all entries that are files/dirs according to include_dirs, hidden, etc., but matching (regex) is done later. So here we collect all potential paths, then later filter by regex match.
                        // For now, collect root if include-dirs (since root is dir). But what about files? Root is dir, not file, so only if include-dirs.
                        // However, walk includes root as dir entry. Should we push root? Yes if include-dirs (for later matching). But what about hidden? Root explicit, so include even if hidden? As observed, explicit hidden dir with -D (no recursive) includes, but that's non-recursive case. For recursive with hidden dir as input and hidden==false, should we include root? Probably yes (explicit), but prune children if hidden? Actually if root is hidden dir, and hidden==false, should we still walk its children? The children are under hidden dir, which is hidden, so they should be excluded? Earlier we saw hidden dir without -x excludes its files. If input is hidden dir itself, and we walk with hidden==false, should we exclude children? Likely yes (since they are under hidden). But root itself (explicit) should still be considered? Let's handle.
                        if include_dirs {
                            // push root path string (as discovered? Use entry.path() string? But need to preserve input string format? For display/dump, should we use discovered path or input path? For root, discovered path is same as input (but may be normalized? Walk gives same as input). Use input string for root to preserve relative/absolute as given? Walk's path may be slightly different (e.g., input "tmp/" with trailing slash vs walk "tmp"). Safer to use input string for root.
                            // Actually for consistency, use entry.path().to_string_lossy() for all, but for root, entry.path() == input (as Path). If input has trailing slash, entry.path() may strip? Unclear. We'll use input for root.
                            out.push(input.clone());
                        }
                        continue;
                    }
                    // depth>0: check hidden
                    if !hidden {
                        // check if any component is hidden? Or just file_name hidden? Walk already prunes? We need to check file_name of entry, and also if parent is hidden? Since we prune hidden dirs, children under hidden dirs won't be visited if we filter_entry to prune. But our current walker doesn't prune, it just filters. So children under hidden dirs would still be visited. To correctly prune, we should check if entry path has hidden component relative to input? Simpler: check file_name hidden, and also skip if parent hidden? Actually if hidden dir is excluded, its children should also be excluded even if children names not hidden. Our simple file_name check would include children like ".hidden/file.txt" where file.txt not hidden, but parent hidden. So need to check all components relative to input? Or use filter to prune.
                        // For now, check if file_name starts with '.' => skip. Additionally, need to handle pruning: if entry is dir and hidden, skip its children by... WalkDir doesn't automatically prune unless we use filter_entry. Since we are using into_iter without filter, hidden dir's children will still be yielded. To prune, we need to check if any ancestor (relative to input) is hidden and skipped? We can check full relative path components.
                        let rel = entry_path.strip_prefix(p).unwrap_or(entry_path);
                        let mut is_hidden_path = false;
                        for comp in rel.components() {
                            if let std::path::Component::Normal(os_str) = comp {
                                if let Some(s) = os_str.to_str() {
                                    if s.starts_with('.') {
                                        is_hidden_path = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if is_hidden_path {
                            // if dir, need to skip? But WalkDir will still descend. To avoid descending, we would need filter_entry. However, since we check each entry's relative path, children under hidden dir will also be flagged as hidden_path (since ancestor hidden), so they will be skipped as well. Good, no need to prune, just skip each.
                            continue;
                        }
                    }
                    // check file type: is_dir vs file (using is_dir which follows symlinks)
                    let is_entry_dir = entry_path.is_dir();
                    // For symlinks, entry.file_type() may be symlink, but is_dir follows. Use is_dir/is_file via path.
                    // Also need to handle broken symlinks: is_dir false, is_file false, but symlink_metadata succeeds. How to treat? For recursive, broken symlink file should be treated as file (like explicit). For dir check, broken symlink is neither file nor dir. What should we do? Earlier broken symlink explicit gave op as file. For recursive, broken symlink should also be file? Let's treat non-dir as file (including broken symlinks, symlinks to files, regular files).
                    if is_entry_dir {
                        if include_dirs {
                            out.push(entry_path.to_string_lossy().to_string());
                        } else {
                            // skip dirs, but still need to descend? Walk will descend regardless. Good.
                        }
                    } else {
                        // file (including symlinks, broken, etc.)
                        // But need to ensure file exists via symlink_metadata? Walk already yields only existing (since it lists dir). Good.
                        out.push(entry_path.to_string_lossy().to_string());
                    }
                }
            } else {
                // non-recursive dir: only consider dir itself if include-dirs
                if include_dirs {
                    out.push(input.clone());
                } else {
                    // nothing
                }
            }
        } else {
            // input is file (or symlink to file, or broken symlink, or other non-dir that exists via symlink_metadata)
            // For explicit files, always include regardless of hidden, recursive, etc. (as observed, hidden explicit included, recursive flag ignored for files)
            // But what about max-depth/hidden with explicit file? They are ignored (since file depth 0). Good.
            out.push(input.clone());
        }
    }
    out
}

fn apply_replacement(re: &Regex, fname: &str, repl: &str, limit: usize, transform: Option<&str>) -> Option<String> {
    // Returns new filename if matched, else None
    // Check if matches? If no match, return None (no op)
    // Use replacen with limit: if limit==0 => replace_all, else replacen(limit)
    // Need to handle transform: upper/lower/ascii applied to replacements?
    // For upper/lower: transform the expanded replacement? How?
    // Observed: upper transforms entire expanded replacement to uppercase (including literals and captures). Similarly lower.
    // For ascii: transliterate expanded replacement to ascii.
    // Implementation: first expand with regex, then transform? Or transform captures before expansion?
    // For upper/lower with captures, both give same (since uppercasing entire expanded == uppercasing captures + literals).
    // For ascii, transliterating entire expanded vs transliterating captures then expanding? Should be same if literals already ascii.
    // Simpler: expand first, then transform the replacement part? But need to be careful: replacement string may contain $1 etc., which after expansion becomes text. Transform should apply to the inserted text, not to the entire filename (which includes prefix/suffix that should not be transformed). Example: file "hello.txt" with expr "l" repl "X" and transform upper: prefix "he" should stay "he" (not uppercased), only replacement "X" uppercased (but X already upper). To test, need case where prefix would be affected if we transformed entire filename.
    // Let's test: file "hello.txt", expr "l", repl "x" (lowercase), transform upper: if transform applies to entire new filename, then "he" prefix would become "HE" as well, giving "HEXXLO"? Or just replacement "X"? Let's test with original.
    // We haven't tested this. Need to test.
    // For now, assume transform applies only to replacement expansions, not to whole filename.
    // How to implement? Use regex::Replacer that transforms captures?
    // Approach: use re.replacen with a custom replacer that expands then transforms?
    // Actually regex crate's replacen takes &str replacement with $ syntax and expands. To transform, we need to expand captures manually, transform them, then assemble.
    // Simpler: get captures, expand manually, transform, then replace?
    // But need to handle limit and multiple matches.
    // Alternative: first do replacement without transform to get intermediate, then... No, need to transform only replaced parts.
    // We can implement by iterating over matches with re.captures_iter and building new string, transforming each replacement expansion.
    // For each match, expand repl using expand() to get replacement text, then transform that text (upper/lower/ascii), then insert.
    // Need to handle $ syntax exactly as regex crate does (including $$, $0, $1, ${1}, etc.). We can use re.replace with NoExpand? No.
    // Easiest: use regex crate's expand functionality: for each match, use caps.expand(repl, &mut dst) to get expanded, then transform dst, then push.
    // Let's implement loop.

    if !re.is_match(fname) {
        return None;
    }
    // If transform is None, just use regex replacen directly
    if transform.is_none() {
        let new = if limit==0 {
            re.replace_all(fname, repl).to_string()
        } else {
            re.replacen(fname, limit, repl).to_string()
        };
        if new==fname { return None; } // Actually if no change? But is_match true, new could still equal old (e.g., repl same as matched)? Then no op (filtered). Our caller also filters, but we can return Some(new) and let caller filter.
        return Some(new);
    }
    let t = transform.unwrap();
    // With transform, need custom
    // Find matches with positions
    // Use re.captures_iter to get all matches up to limit (or all if limit==0)
    // But need to handle overlapping? Regex non-overlapping leftmost. Captures_iter does that.
    let mut result = String::new();
    let mut last_end = 0;
    let mut count = 0;
    for caps in re.captures_iter(fname) {
        if limit!=0 && count>=limit { break; }
        let m = caps.get(0).unwrap();
        // push prefix
        result.push_str(&fname[last_end..m.start()]);
        // expand replacement for this match
        let mut expanded = String::new();
        caps.expand(repl, &mut expanded);
        // transform expanded
        let transformed = match t {
            "upper" => expanded.to_uppercase(),
            "lower" => expanded.to_lowercase(),
            "ascii" => to_ascii_str(&expanded),
            _ => expanded,
        };
        result.push_str(&transformed);
        last_end = m.end();
        count+=1;
        // Avoid infinite loop for empty match? Regex can match empty string (e.g., ".*"? Actually ".*" matches empty at end? For "a" with expr "b*"?? Need to handle empty matches like regex crate does (it advances by one char after empty). Our loop using captures_iter already handles empty correctly (it advances). Good.
        // But need to handle that replacen with limit counts replacements, not matches? Same.
    }
    result.push_str(&fname[last_end..]);
    Some(result)
}

fn handle_operations(mut ops: Vec<(String,String)>, is_dry: bool, is_silent: bool, use_color_out: bool, use_color_err: bool, do_backup: bool, should_dump: bool, dump_prefix: String) {
    // Filter no-change? Already filtered in callers for regex/to-ascii (where new==old skipped). For from-file, we filtered s!=t. Good. But also need to filter? For safety, retain s!=t.
    ops.retain(|(s,t)| s!=t);
    // Check same-name conflicts: same target
    // Build map target -> list of sources
    let mut target_to_sources: HashMap<String, Vec<String>> = HashMap::new();
    for (s,t) in &ops {
        target_to_sources.entry(t.clone()).or_default().push(s.clone());
    }
    // Find duplicates
    let mut same_name_blocks: Vec<(String, Vec<String>)> = Vec::new(); // (target, sources)
    for (t, sources) in &target_to_sources {
