        // For each target with duplicates, let first = sources[0] (in ops order), then for each other in sources[1..], emit block first->target + other->target
        // But what about multiple targets? Each target's blocks separate with blank line.
        // Our earlier test with two targets (aX and bX) gave two blocks (one per target), each with 2 entries. That's consistent with pairwise per target (since each target had exactly 2 sources, one block each).
        // For 3 sources same target, gives 2 blocks (first+second, first+third). Good.
        if !is_silent {
            if is_dry {
                print_header(use_color_out, is_silent);
            }
            // Build details string
            let mut details = String::new();
            // Need to sort blocks? Order nondeterministic in original. For deterministic, sort by target? Or preserve ops order? Let's preserve order of first occurrence in ops.
            // Find order of targets by first occurrence in ops
            let mut target_order: Vec<String> = Vec::new();
            let mut seen = HashSet::new();
            for (_,t) in &ops {
                if target_to_sources[t].len()>1 && !seen.contains(t) {
                    seen.insert(t.clone());
                    target_order.push(t.clone());
                }
            }
            for target in target_order {
                let sources = &target_to_sources[&target];
                let first = &sources[0];
                for other in &sources[1..] {
                    details.push_str(&format!("{}->{}\n{}->{}\n\n", first, target, other, target));
                    // Note: no spaces around -> for details (as observed)
                }
            }
            // Remove trailing? Details already ends with \n\n (blank line). Good.
            if use_color_err {
                eprint!("{}Error: {}Files will have the same name\n{}{}\n{}{}{}\n", RED, RESET, RED, RED, details, RESET, RESET);
                // Wait observed always is: RED Error: RESET Files... \n RED RED \n details \n RESET RESET \n
                // Our format: RED Error: RESET Files...\n + RED RED \n + details + RESET RESET \n ?
                // Actually details already ends with \n\n (blank). And we add extra? Let's construct exactly:
                // Never: "Error: Files will have the same name\n\n" + details (where details is blocks each ending with \n\n) ??? Actually never's full is "Error: ...\n\n" + blocks. Blocks already include \n\n each. So total: header line + blank line + blocks.
                // Always: "RED Error: RESET Files...\n" + "RED RED \n" + details + "RESET RESET \n" ??? Let's check raw: 'RED Error: RESET Files...\n' + 'RED RED \n' + '...a1->... \n...a2->... \n' + 'RESET RESET \n' ??? Actually raw ends with '...aX.txt\nRESET RESET \n' where '...aX.txt\n' is last detail line newline, then RESET RESET newline. While never ends with '...aX.txt\n\n' (detail newline + blank newline). So always replaces blank lines with colored blanks? The initial blank after header (never '\n\n' = header newline + blank) becomes in always header newline + 'RED RED \n' (which is RED RED newline, i.e., colored blank). And final blank becomes 'RESET RESET \n'? Hmm.
                // Simpler: replicate exactly as observed:
