fn collect_candidates(paths: &[String], include_dirs: bool, recursive: bool, max_depth: Option<usize>, hidden: bool) -> Vec<String> {
    let mut out = Vec::new();
    for input in paths {
        let p = Path::new(input);
        if fs::symlink_metadata(p).is_err() { continue; }
        let is_dir = p.is_dir();
        if is_dir {
            if recursive {
                let mut builder = walkdir::WalkDir::new(p);
                if let Some(d) = max_depth { builder = builder.max_depth(d); }
                let walker = builder.into_iter();
                for entry in walker {
                    let entry = match entry { Ok(e) => e, Err(_) => continue };
                    let entry_path = entry.path();
                    let depth = entry.depth();
                    if depth == 0 {
                        if include_dirs { out.push(input.clone()); }
                        continue;
                    }
                    if !hidden {
                        let rel = entry_path.strip_prefix(p).unwrap_or(entry_path);
                        let mut is_hidden_path = false;
                        for comp in rel.components() {
                            if let std::path::Component::Normal(os_str) = comp {
                                if let Some(s) = os_str.to_str() {
                                    if s.starts_with('.') { is_hidden_path = true; break; }
                                }
                            }
                        }
                        if is_hidden_path { continue; }
                    }
                    let is_entry_dir = entry_path.is_dir();
                    if is_entry_dir {
                        if include_dirs { out.push(entry_path.to_string_lossy().to_string()); }
                    } else {
                        out.push(entry_path.to_string_lossy().to_string());
                    }
                }
            } else {
                if include_dirs { out.push(input.clone()); }
            }
        } else {
            out.push(input.clone());
        }
    }
    out
}

fn apply_replacement(re: &Regex, fname: &str, repl: &str, limit: usize, transform: Option<&str>) -> Option<String> {
    if !re.is_match(fname) { return None; }
    if transform.is_none() {
        let new = if limit == 0 { re.replace_all(fname, repl).to_string() } else { re.replacen(fname, limit, repl).to_string() };
        return Some(new);
    }
    let t = transform.unwrap();
    let mut result = String::new();
    let mut last_end = 0;
    let mut count = 0;
    for caps in re.captures_iter(fname) {
        if limit != 0 && count >= limit { break; }
        let m = caps.get(0).unwrap();
        result.push_str(&fname[last_end..m.start()]);
        let mut expanded = String::new();
        caps.expand(repl, &mut expanded);
        let transformed = match t {
            "upper" => expanded.to_uppercase(),
            "lower" => expanded.to_lowercase(),
            "ascii" => to_ascii_str(&expanded),
            _ => expanded,
        };
        result.push_str(&transformed);
        last_end = m.end();
        count += 1;
    }
    result.push_str(&fname[last_end..]);
    Some(result)
}

