                let src_path = Path::new(s);
                if !src_path.is_dir() {
                    let mut bk = format!("{}.bk", s);
                    if fs::symlink_metadata(&bk).is_ok() {
                        let mut i = 1;
                        loop {
                            let cand = format!("{}.bk.{}", s, i);
                            if fs::symlink_metadata(&cand).is_err() { bk = cand; break; }
                            i += 1;
                        }
                    }
                    if fs::copy(s, &bk).is_ok() {
                        if !is_silent {
                            if use_color_out {
                                print!("{} Backup created - {}{}{}\n", format!("{}{}{}", BOLD, "Info: ", RESET), format!("{}{}", GREY, format!("{} -> {}", s, bk)), RESET);
                            } else {
                                print!("Info:  Backup created - {} -> {}\n", s, bk);
                            }
                        }
                    }
                }
            }
            match fs::rename(s, t) {
                Ok(_) => {
                    if !is_silent {
                        print!("{}", print_operation(s, t, use_color_out));
                    }
                }
                Err(e) => {
                    if !is_silent {
                        if use_color_err {
                            eprint!("{}Error: {}Cannot rename {}{}{}\n", RED, RESET, RED, format!("{} -> {}\n{}", s, t, e), RESET);
                        } else {
                            eprint!("Error: Cannot rename {} -> {}\n{}\n", s, t, e);
                        }
                    }
                    std::process::exit(1);
                }
            }
        }
    }
}
