    return r
def run_new(*args, cwd="/workspace"):
    r = subprocess.run(["/workspace/target/debug/rnr"]+list(args), capture_output=True, text=True, cwd=cwd)
    return r
def test_case(desc, args, setup=None, sort=True):
    tmp1=tempfile.mkdtemp(); tmp2=tempfile.mkdtemp()
    for tmp in [tmp1, tmp2]:
        if setup: setup(tmp)
    def run_on_tmp(run_func, tmp):
        real_args=[a.replace("TMP", tmp) if "TMP" in a else a for a in args]
        return run_func(*real_args, cwd=tmp)
    r1=run_on_tmp(run_orig, tmp1); r2=run_on_tmp(run_new, tmp2)
    def norm(s, tmp): return s.replace(tmp, "TMP")
    o1_out, o1_err = norm(r1.stdout, tmp1), norm(r1.stderr, tmp1)
    o2_out, o2_err = norm(r2.stdout, tmp2), norm(r2.stderr, tmp2)
    def sort_lines(s):
        if not s: return s
        lines=s.splitlines()
        if len(lines)<=1: return s
        # Keep first line (header or error header) and sort rest?
        # For stdout dry, first line is header, rest sorted. For force, no header, sort all.
        if lines[0].endswith("DRY-RUN") or lines[0].startswith("This is"):
            return lines[0]+"\n"+"\n".join(sorted(lines[1:]))+("\n" if s.endswith("\n") else "")
        else:
            return "\n".join(sorted(lines))+("\n" if s.endswith("\n") else "")
    if sort:
        o1_out, o2_out = sort_lines(o1_out), sort_lines(o2_out)
        o1_err, o2_err = sort_lines(o1_err), sort_lines(o2_err)
    match = (o1_out==o2_out and o1_err==o2_err and r1.returncode==r2.returncode)
    print(f"{'PASS' if match else 'FAIL'}: {desc}")
