import subprocess, tempfile, os, shutil, json

def probe_range(start, end, batch_size=500):
    result = {}
    tmp = tempfile.mkdtemp()
    chars = []
    for code in range(start, end+1):
        if code in (0x00, 0x2F):
            continue
        if 0xD800 <= code <= 0xDFFF:
            continue
        try:
            c = chr(code)
        except:
            continue
        chars.append(c)
    print(f"Probing {len(chars)} chars from {start:04X} to {end:04X} in batches of {batch_size}")
    for i in range(0, len(chars), batch_size):
        batch = chars[i:i+batch_size]
        # cleanup
        for f in os.listdir(tmp):
            try: os.remove(os.path.join(tmp, f))
            except: pass
        for c in batch:
            hexcode = f"{ord(c):04X}"
            fname = f"{hexcode}_{c}.txt"
            try:
                open(os.path.join(tmp, fname), "w").write("x")
            except Exception as e:
                print(f"create failed {hexcode} {e}")
                continue
        paths = [os.path.join(tmp, f) for f in os.listdir(tmp)]
        r = subprocess.run(["/workspace/executable", "to-ascii"] + paths + ["--color", "never", "-f", "--no-dump"], capture_output=True, text=True, cwd="/workspace")
        # After force, list new files
        new_files = os.listdir(tmp)
        new_by_hex = {}
        for f in new_files:
            if "_" not in f:
                continue
            hexpart, rest = f.split("_", 1)
            # rest is ascii + ".txt" or for files with no change? Actually force renames, so new files are ascii versions
            # For files with no change (ascii already? But our batch is non-ascii, so all changed? Except some map to themselves? Unlikely)
            # For control chars mapping to "", rest is ".txt"? Actually new file is "HEX_.txt" (hex + "_" + "" + ".txt")
            if rest.endswith(".txt"):
                ascii_part = rest[:-4]
            else:
                ascii_part = rest
            new_by_hex[hexpart] = ascii_part
        for c in batch:
            hexcode = f"{ord(c):04X}"
            if hexcode in new_by_hex:
                result[c] = new_by_hex[hexcode]
            else:
                print(f"missing {hexcode}")
                result[c] = ""
        if i % 2000 == 0:
            print(f"  batch {i}/{len(chars)} done")
    shutil.rmtree(tmp)
    return result

# Probe BMP 0x80-0xFFFF
res = probe_range(0x80, 0xFFFF, batch_size=500)
print(f"Total {len(res)}")
# Save
import json as j
# Convert to hex mapping for Rust generation
with open("/tmp/bmp_mapping.json","w") as f:
    j.dump({f"{ord(k):04X}": v for k,v in res.items()}, f, ensure_ascii=False)
print("saved")
